const CACHE='astris-offline-v10';
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(['./','./index.html','./style.css','./redesign.css','./enhancements.css','./analysis-v2.css','./dashboard.css','./research.css','./ground.css','./verification.css','./clarity.css','./transport.js','./leadtime.js','./benchmark.js','./verification-ui.js','./operator.js','./research.js','./forecast.js','./sensor-config.js','./analytics.js','./human-mesh.js','./human-view.js','./portraits.js','./assets/a1.jpg','./assets/a2.jpg','./assets/a3.jpg','./assets/a4.jpg','./assets/a5.jpg','./assets/a6.jpg','./engine.js','./app.js','./icon.svg'])).then(()=>self.skipWaiting()));});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(c=>c.put(event.request,copy));}return response;}).catch(()=>caches.match(event.request).then(r=>r||(event.request.mode==='navigate'?caches.match('./index.html'):Response.error()))));});
